from _lib import *

DEF2 = module("DEF2", "Defence 2: reading an incident - what the logs say happened, in order", "Security",
  "When something goes wrong on a machine, the logs hold the story - if you can read them. This module is the defender's other half: not stopping the break-in, but reconstructing it afterward from the evidence, calmly and in order. You practise entirely on your own Pi, on events you create yourself.",
  "Abid", "A clear 'what happened and when' timeline she builds for Abid from a sequence of events she staged on her own Pi, written the way a real incident report reads.",
  [
    lesson("DEF2-L1", "Logs are a diary: where they live, how to read time, and how to follow one thread",
      ["List the main logs on her Pi (auth, web, system, her own app) and what each records", "Read timestamps across logs and line events up in time (the skill: one clock, many diaries)", "Follow one real request of her own from the web log to the app log"],
      FROM_ZERO + LINUX + LAB + "A machine writes down what happens; a defender reads it back. On her Pi: journalctl (system + services), nginx access/error, her noticeboard's own log, auth for logins. All in UTC or local - she learns to normalise time (the thing that makes a timeline possible). She loads her own noticeboard, then traces that single request across the web log and the app log, matching timestamps. Check: three logs and what each holds; why one clock matters."),
    lesson("DEF2-L2", "Normal, then not normal: a baseline and the art of noticing",
      ["Re-use her DEF1 baseline and define what a quiet hour looks like in each log", "Stage a benign 'event' on her own Pi (a burst of failed logins she generates, a 404 scan of her own site) and find it", "Explain signal vs noise: most log lines are boring, and that is the point"],
      FROM_ZERO + LINUX + LAB + "To see the strange you must know the ordinary (DEF1-L5). She records what a calm ten minutes looks like. Then SHE stages a visible event against her OWN Pi only (stating the lab rule): a handful of deliberately failed ssh logins with a wrong user, or a quick request for ten missing pages on her own site - all generated by her, on her machine. She finds the burst in the log, among the noise. The skill is noticing the shape (many fails, fast, one source). Check: what her staged event looks like in the log; signal vs noise."),
    lesson("DEF2-L3", "The timeline: turning scattered lines into one story",
      ["Pull the relevant lines from several logs with grep/awk (CS4) and sort them into one ordered list", "Write the story in plain words: first this, then this, which caused this", "State what she can prove from the logs and what she can only guess - the honest line"],
      FROM_ZERO + LINUX + LAB + "The deliverable. She stages a short sequence on her Pi (a login from her laptop, a page served, a config change she makes, a service restart), then reconstructs it from the logs alone, as if she did not already know - grep the actors, awk the times, sort into one list, write the story. The discipline that separates a report from a guess: mark each step 'proven by log X' or 'inferred'. This is exactly how a real incident is written up. The gift is this timeline. Check: her timeline is in time order and marks proof vs guess."),
    lesson("DEF2-H1", "Horizon: security operations, SIEMs and the people who watch at 3am",
      ["Explain what a Security Operations Centre does and what a SIEM is (all the logs in one searchable place - her grep, scaled)", "Explain alert fatigue with base rates (M14): too many false alarms and the real one is missed", "Explain responsible, calm incident response (contain, understand, fix, learn) and why panic makes it worse"],
      HORIZON + "Her Pi work is the seed of a real job: teams watch thousands of machines' logs gathered into one searchable system (a SIEM - her grep and timeline, scaled to millions of lines). The human problem she can now understand with maths: alert fatigue - a detector with even a 1% false rate buries the true attack (base rates, M14), so tuning matters as much as detecting. The calm method: contain, understand, fix, learn - and write it up so it does not happen twice (the blameless post-mortem). Boundary Question: 'Your alarm fires 500 times a day and 3 are real. What do you change, and what number tells you it worked?'"),
    check("DEF2-C", "Defence 2 checkpoint", ["logs-and-timestamps", "baseline-and-anomaly", "build-a-timeline", "proof-vs-inference"], count=10),
    teach("DEF2-T", "Explain to Abid how you would figure out what happened on a computer after something went wrong, using the words log, timeline and proof. Then say why too many false alarms is a real danger. Say it out loud first, then write it. 5-7 sentences."),
  ])

AI2 = module("AI2", "AI 2: your Companion gets a voice - speech in, speech out, and the honest limits", "AI",
  "Your Companion runs on your Pi and has a personality you wrote. Now it listens and speaks: you turn sound into text, text into sound, and wire them to the model you already run. You also face, honestly, what a listening device in a home means - and build yours the way you would want one built.",
  "the family", "The Companion holding a short spoken exchange with the family, entirely offline on the Pi, with a push-to-talk button so it only listens when asked - demonstrated on a call.",
  [
    lesson("AI2-L1", "Sound is numbers: how a microphone becomes data, and back",
      ["Explain how a microphone turns air into numbers (sampling) and a speaker turns numbers into air - tie to analog vs digital (CS1, HW1)", "Record a short clip on the Pi and look at it; play it back", "Explain what speech-to-text and text-to-speech each do, as steps"],
      FROM_ZERO + LINUX + LAB + "A microphone samples the pressure of air thousands of times a second into numbers (CS1's digital, HW1's analogRead, now sound); a speaker reverses it. She records a clip (arecord), sees the file, plays it (aplay). The two converters: speech-to-text (STT: sound numbers -> words) and text-to-speech (TTS: words -> sound numbers). Honest expectation: on a Pi these are small models, imperfect - like her Companion. Check: sampling in her words; what STT and TTS each do."),
    lesson("AI2-L2", "Listening: speech-to-text on the Pi, offline",
      ["Install a small offline speech-to-text engine and transcribe her own voice", "Explain why offline matters here (a microphone that only ever sends sound away is a surveillance device - her choice, AI1)", "Measure the honest accuracy and the delay, and accept them"],
      FROM_ZERO + LINUX + LAB + "A small offline STT (the tutor names the best light one that month - e.g. a tiny whisper build or vosk); she transcribes herself and reads the result, errors and all. The privacy point made concrete: STT in the cloud means her voice leaves the house; offline means it never does - the same choice as the local model (AI1), now about her actual voice. She measures accuracy and the pause. Check: why offline STT matters; her measured accuracy."),
    lesson("AI2-L3", "Speaking, and wiring the loop: button -> listen -> think -> speak",
      ["Install offline text-to-speech and make the Pi say a sentence", "Wire the full loop: a push-to-talk button (HW1) -> STT -> the Ollama model (AI1) -> TTS", "Explain push-to-talk as a safety and privacy choice, in her words"],
      FROM_ZERO + LINUX + LAB + "Offline TTS (espeak-ng or piper); the Pi speaks. Then the whole Companion comes together: her button (HW1) starts listening, STT makes words, her model with its personality and rules answers (AI1), TTS speaks it - a script she writes joining the four. PUSH-TO-TALK is deliberate: it listens only while the button is held, so it is not an always-on ear - she explains why she chose that (a listening device you do not control is the thing SS5/DEF1 warned about). The gift runs. Check: the four stages of the loop; why push-to-talk."),
    lesson("AI2-H1", "Horizon: voice assistants, always-on microphones, and building one you would trust",
      ["Explain how commercial voice assistants work (wake word on device, the rest in the cloud) and what that means for privacy", "Explain the attacks on voice (recordings, wake-word mistakes, voice cloning) as phenomena, defensively", "Ask who benefits, how would you break it, how would you fix it - for a home assistant, and show hers is the answer"],
      HORIZON + "How the ones people buy work: a wake word is caught on the device, then the audio goes to the company's servers - so a mistake or a breach means private speech leaves the home. Attacks as phenomena, defensively: stored recordings leaking, false wake-ups recording by accident, and voice cloning (a model trained to sound like someone - the deepfake problem, which is why a voice alone is weak proof - tie to CRYPTO1's signatures as real proof). Her build is the fix: offline, push-to-talk, her rules. Boundary Question: 'A home assistant is always listening. Name three ways that trust breaks, and show which your Companion's design prevents.'"),
    teach("AI2-T", "Explain to a 10-year-old how your Companion hears and speaks, and why you made it listen only when a button is pressed and work without the internet. Say it out loud first, then write it. 5-7 sentences."),
  ])

MODULES = [DEF2, AI2]
